{
  "schemaVersion": "0.2",
  "slug": "tooltip",
  "name": "Tooltip",
  "status": "experimental",
  "purpose": "Displays supplementary information for a control on hover or focus.",
  "scenarios": [
    "Explain an icon button on hover",
    "Show a keyboard shortcut on focus",
    "Provide a hint for a form field"
  ],
  "props": {
    "trigger": {
      "type": "node",
      "required": true,
      "description": "Element that opens the tooltip on hover or focus."
    },
    "content": {
      "type": "node",
      "required": true,
      "description": "Content shown inside the tooltip."
    },
    "openDelay": {
      "type": "number",
      "required": false,
      "description": "Delay in milliseconds before the tooltip opens.",
      "default": 300
    },
    "closeDelay": {
      "type": "number",
      "required": false,
      "description": "Delay in milliseconds before the tooltip closes.",
      "default": 100
    }
  },
  "variants": [],
  "states": [
    {
      "name": "open",
      "description": "Tooltip is visible."
    },
    {
      "name": "closed",
      "description": "Tooltip is not visible."
    }
  ],
  "composition": {
    "allowedParents": [
      "button",
      "input",
      "page"
    ],
    "allowedChildren": [
      "text"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not put essential instructions only in a tooltip.",
    "Do not open a tooltip from a touch event without an alternative control."
  ],
  "a11y": {
    "role": "tooltip",
    "keyboard": [
      "Focus the trigger to show the tooltip"
    ],
    "focus": "Tooltip follows the trigger focus and pointer hover.",
    "labeling": "Tooltip content is associated with the trigger via aria-describedby.",
    "wcag": [
      "1.3.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Tooltip stays within the viewport and avoids clipping on compact screens.",
    "breakpoints": {
      "compact": "Tooltip is not the primary touch interaction; an explicit control is preferred.",
      "medium": "Tooltip appears on hover and focus.",
      "large": "Tooltip appears on hover and focus."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Tooltip positioning follows the document direction.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "tooltip",
    "states": [
      "open",
      "closed"
    ],
    "intents": [
      "explain-on-hover"
    ]
  }
}

{
  "tooltip": {
    "hint": "詳細情報",
    "shortcut": "キーボードショートカット"
  }
}

.cu-tooltip__trigger {
  display: inline-flex;
}

.cu-tooltip {
  max-inline-size: 16rem;
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-2);
  border-radius: var(--cu-radius-sm);
  color: var(--cu-color-fg-inverse);
  background: var(--cu-color-background-inverse);
  font-size: 0.875rem;
  line-height: 1.4;
  box-shadow: 0 4px 12px color-mix(in srgb, var(--cu-color-background-inverse) 16%, transparent);
}

import { TooltipPrimitive } from '@chameleon-ui/primitives'
import type { ReactNode } from 'react'
import './styles.css'

export interface TooltipProps {
  trigger: ReactNode
  content: ReactNode
  openDelay?: number
  closeDelay?: number
  className?: string
}

export function Tooltip({ trigger, content, openDelay = 300, closeDelay = 100, className }: TooltipProps) {
  const classes = ['cu-tooltip', className].filter(Boolean).join(' ')

  return (
    <TooltipPrimitive.Root closeDelay={closeDelay} openDelay={openDelay}>
      <TooltipPrimitive.Trigger asChild className="cu-tooltip__trigger">
        {trigger}
      </TooltipPrimitive.Trigger>
      <TooltipPrimitive.Positioner className="cu-tooltip__positioner">
        <TooltipPrimitive.Content
          className={classes}
          data-ai-role="tooltip" data-ai-intent="explain-on-hover"
          data-ai-state="open"
          role="tooltip"
        >
          {content}
        </TooltipPrimitive.Content>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Root>
  )
}
